{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Timolol shares the tert-butylamino-2-hydroxypropoxy aryl ether core and has absolute oral bioavailability 61.0 ± 19.2% in humans, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Metoprolol, another aryloxypropanolamine beta-blocker, has absolute oral bioavailability 38 ± 14% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Flecainide, a polar aryl ether/amide drug, has mean systemic availability 90-95% after oral administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Safinamide has absolute oral bioavailability 95% in healthy subjects, supporting high F for a small oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Perindopril has absolute oral bioavailability 65-75%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Propranolol, a close beta-blocker analog, has mean oral bioavailability 27% with range 17-33% in normal subjects, supporting F >= 20% on average.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Propranolol showed 19% oral bioavailability in healthy volunteers, below the threshold; this is the main contradictory evidence from a close analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer analogs with the same beta-blocker aryloxypropanolamine or polar aryl ether motif show absolute oral bioavailability well above 20%: timolol 61%, metoprolol 38%, flecainide 90-95%, safinamide 95%, perindopril 65-75%. The query's tert-butylamino-hydroxypropoxy and urea/cyclohexyl structure resembles timolol and metoprolol more than propranolol, and the single low propranolol record (19%) is outweighed. Prediction: high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "First-pass metabolism and absorption of the urea/cyclohexyl substituent are not directly characterized.",
    "Propranolol variability shows beta-blocker first-pass liability, but query-specific metabolic stability is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

